<template>
  <section class="qh-page" data-testid="qa-health" :data-mobile-view="mobileDetail ? 'detail' : 'list'" :aria-label="$t('qaHealth.title')">
    <header class="qh-header">
      <div><div class="qh-title-line"><h1>{{ $t('qaHealth.title') }}</h1><span class="qh-preview-label">{{ $t(preview ? 'qaHealth.preview' : 'qaHealth.live.observed') }}</span></div><p>{{ $t('qaHealth.subtitle') }}</p></div>
      <div class="qh-context"><span>{{ $t('qaHealth.environment') }} <b>{{ model.environment }}</b></span><span>{{ $t('qaHealth.version') }} <code>{{ model.version || $t('qaHealth.live.versionUnknown') }}</code></span><span>{{ $t('qaHealth.updated') }} <time :datetime="model.observedAt">{{ snapshotStamp }}</time></span><button class="qa-icon-button" data-testid="health-refresh" :disabled="loading" :aria-label="$t(preview ? 'qaHealth.refresh' : 'qaHealth.live.refresh')" @click="refreshPreview"><QaIcon name="refresh" aria-hidden="true" /></button></div>
    </header>
    <p v-if="refreshed && preview" class="qh-refresh-note" role="status">{{ $t('qaHealth.refreshed') }}</p>
    <p v-if="!design" class="qh-scope">{{ $t('qaHealth.live.scope') }}</p>
    <div class="qh-observation-bar" data-testid="health-coverage" :aria-label="$t('qaHealth.observationCoverage')">
      <div class="qh-observation-counts"><span v-for="state in countStates" :key="state" :class="'qh-tone-' + (state === 'unknown' ? 'stale' : state)"><QaIcon :name="statusIcon(state)" aria-hidden="true" />{{ $t('qaHealth.countLabels.' + state) }} <b>{{ overview.counts[state] }}</b></span></div>
      <span class="qh-coverage">{{ $t('qaHealth.observationCoverage') }} <strong>{{ overview.observed }}/{{ overview.total }}</strong><small>{{ coverageLabel }}</small></span>
    </div>
    <div class="qh-summary" :aria-label="$t('qaHealth.summary')">
      <div v-for="item in overview.groups" :key="item.id" :data-testid="'health-summary-' + item.id" :class="'qh-tone-' + item.tone"><QaIcon :name="statusIcon(item.tone)" aria-hidden="true" /><div><strong>{{ $t((design ? 'qaHealth.groupNames.' : 'qaHealth.live.groupNames.') + item.id) }}{{ $t('qaHealth.groupStates.' + item.tone) }}</strong><span class="qh-summary-description">{{ $t('qaHealth.groupCoverage', { n: item.observed, total: item.total }) }}<template v-if="item.warning"> · {{ $t('qaHealth.groupWarnings', { n: item.warning }) }}</template></span><small class="qh-summary-observed"><span>{{ $t('qaHealth.observed') }} </span><time>{{ item.observedAt || $t('qaHealth.notMeasured') }}</time></small></div></div>
      <div class="qh-tone-stale"><QaIcon name="info" aria-hidden="true" /><div><strong><span class="qh-summary-full">{{ $t(design ? 'qaHealth.summaryItems.quality.title' : 'qaHealth.live.qualityUnmeasured') }}</span><span class="qh-summary-short">{{ $t(design ? 'qaHealth.qualityShort' : 'qaHealth.live.qualityShort') }}</span></strong><span class="qh-summary-description">{{ $t('qaHealth.summaryItems.quality.description') }}</span><small class="qh-summary-observed">{{ $t('qaHealth.reviewNotMeasured') }}</small></div></div>
    </div>
    <p v-if="overview.unknowns.length" class="qh-observation-note" data-testid="health-observation-note"><QaIcon name="info" aria-hidden="true" />{{ $t('qaHealth.observationNote', { modules: overview.unknowns.map(moduleName).join('、') }) }}</p>
    <div class="qh-workspace">
      <aside ref="master" class="qh-master" :aria-label="$t('qaHealth.modulesLabel')">
        <h2 ref="listHeading" tabindex="-1">{{ $t('qaHealth.moduleStates') }}</h2>
        <div class="seg-ctl qh-filters" role="group" :aria-label="$t('qaHealth.moduleFilter')"><button data-testid="health-filter-issues" :class="{on: filter === 'issues'}" :aria-pressed="filter === 'issues'" @click="filter = 'issues'">{{ $t('qaHealth.currentIssues') }} ({{ issues.length + unobserved.length }})</button><button data-testid="health-filter-all" :class="{on: filter === 'all'}" :aria-pressed="filter === 'all'" @click="filter = 'all'">{{ $t('qaHealth.allModules') }} ({{ modules.length }})</button></div>
        <h3 v-if="filter === 'issues'" class="qh-group-heading" data-testid="health-observed-issues">{{ $t('qaHealth.observedIssues') }} <span>({{ issues.length }})</span></h3>
        <div class="qh-module-list">
          <button v-for="item in shownModules" :key="item.id" :ref="(element) => rememberModuleButton(item.id, element)" :data-testid="'health-module-' + item.id" :class="['qh-module', 'qh-tone-' + item.status, { 'is-selected': selectedId === item.id }]" :aria-pressed="selectedId === item.id" @click="selectModule(item.id)"><QaIcon :name="statusIcon(item.status)" aria-hidden="true" /><span><strong>{{ moduleName(item) }}{{ item.status === 'healthy' ? '' : ' ' + (design ? $t('qaHealth.modules.' + item.id + '.short') : $t('qaHealth.status.' + item.status)) }}</strong><small>{{ moduleList(item) }}</small></span><QaIcon name="chevron_right" aria-hidden="true" /></button>
        </div>
        <template v-if="filter === 'issues'">
          <template v-if="unobserved.length"><h3 class="qh-group-heading" data-testid="health-unobserved-modules">{{ $t('qaHealth.unobservedModules') }} <span>({{ unobserved.length }})</span></h3><div class="qh-module-list"><button v-for="item in unobserved" :key="item.id" :ref="(element) => rememberModuleButton(item.id, element)" :data-testid="'health-module-' + item.id" :class="['qh-module', 'qh-tone-' + item.status, { 'is-selected': selectedId === item.id }]" :aria-pressed="selectedId === item.id" @click="selectModule(item.id)"><QaIcon :name="statusIcon(item.status)" aria-hidden="true" /><span><strong>{{ moduleName(item) }} {{ design ? $t('qaHealth.modules.' + item.id + '.short') : $t('qaHealth.status.' + item.status) }}</strong><small>{{ moduleList(item) }}</small></span><QaIcon name="chevron_right" aria-hidden="true" /></button></div></template>
          <h3 class="qh-healthy-heading">{{ $t('qaHealth.healthyModules') }} <span>({{ healthy.length }})</span></h3><div class="qh-healthy-list"><button v-for="item in healthy" :key="item.id" :ref="(element) => rememberModuleButton(item.id, element)" :data-testid="'health-module-' + item.id" :aria-pressed="selectedId === item.id" @click="selectModule(item.id)"><QaIcon name="check_circle_filled" aria-hidden="true" /><span>{{ moduleName(item) }}</span><small>{{ $t('qaHealth.status.healthy') }}</small></button></div><button class="qa-text-link qh-all-link" @click="filter = 'all'">{{ $t('qaHealth.viewAll') }} ({{ modules.length }})<QaIcon name="chevron_right" aria-hidden="true" /></button>
        </template>
      </aside>
      <article ref="detail" class="qh-detail" data-testid="health-detail" tabindex="-1" :aria-labelledby="'health-detail-title'" :class="'qh-tone-' + selected.status">
        <div v-if="mobileDetail" class="qh-mobile-detail-bar"><button class="qa-text-link" data-testid="health-back-to-issues" @click="returnToIssues"><QaIcon name="arrow_back" aria-hidden="true" />{{ $t('qaHealth.backToIssues') }}</button><span class="qh-preview-label">QA · {{ $t(preview ? 'qaHealth.shortPreview' : 'qaHealth.live.observed') }}</span></div>
        <div class="qh-eyebrow">{{ $t('qaHealth.modules.' + selected.id + '.group') }} / {{ selected.name === 'collector' ? 'COLLECTOR' : selected.name.toUpperCase() }}</div>
        <div class="qh-detail-heading"><div><h2 id="health-detail-title">{{ moduleTitle(selected) }}</h2><span class="qh-status">{{ $t('qaHealth.status.' + selected.status) }}</span></div><button ref="evidenceButton" class="qa-button qa-primary qh-evidence-button" data-testid="health-evidence" @click="openEvidence"><QaIcon name="description" aria-hidden="true" />{{ $t('qaHealth.evidence') }}</button></div>
        <p class="qh-impact" data-testid="health-impact">{{ $t((design ? 'qaHealth.modules.' + selected.id + '.impact' : 'qaHealth.live.impacts.' + selected.id)) }}</p>
        <p v-if="!design && ['llm_no_recent_requests', 'llm_inconclusive', 'llm_observation_unavailable'].includes(selected.reason)" class="qh-current-note" data-testid="health-llm-notice" role="note">{{ $t('qaHealth.live.reasons.' + selected.reason) }}</p>
        <dl v-if="!design && Object.keys(visibleDetails).length" class="qh-run-counts" data-testid="health-run-counts"><div v-for="(value, key) in visibleDetails" :key="key"><dt>{{ $t('qaHealth.live.details.' + key) }}</dt><dd :class="{ 'has-failure': failedDetail(key, value) }">{{ formatDetail(key, value) }}</dd></div></dl>
        <p v-if="!design && selected.details.window_limited" class="qh-observation-note" data-testid="health-llm-limited">{{ $t('qaHealth.live.llmLimited') }}</p>
        <dl class="qh-measurements"><div><dt>{{ moduleMetric(selected) }}</dt><dd :class="{ 'qh-measured': design || thresholdRatio }">{{ formatValue(selected.value, selected.unit) }}</dd><small v-if="thresholdRatio" class="qh-threshold-relation" data-testid="health-threshold-ratio">{{ $t('qaHealth.thresholdRatio', { ratio: thresholdRatio }) }}</small></div><div><dt>{{ $t('qaHealth.threshold') }}</dt><dd>{{ formatValue(selected.threshold, selected.unit) }}<small v-if="selected.id === 'agent' && selected.threshold !== null">{{ $t('qaHealth.minimum') }}</small></dd></div><div><dt>{{ selected.pending === null ? $t('qaHealth.observed') : $t('qaHealth.pending') }}</dt><dd>{{ selected.pending === null ? selected.observedAt?.slice(-8) || '—' : selected.pending }}<small v-if="selected.pending !== null">{{ $t('qaHealth.articles') }}</small></dd></div></dl>
        <div class="qh-score-line"><span>{{ $t('qaHealth.healthIndex') }} <strong data-testid="health-score">—</strong><small>{{ $t('qaHealth.notScored') }}</small></span><details class="qh-rules" data-testid="health-rules"><summary><QaIcon name="info" aria-hidden="true" />{{ $t('qaHealth.rules') }}</summary><p>{{ $t('qaHealth.rulesDescription') }}</p></details></div>
        <QaHealthHistory v-if="!preview" :module-id="selected.id" :refresh-key="model.observedAt" :current-reason="selected.reason" />
        <QaHealthTrend v-else-if="selected.samples.length" :samples="selected.samples" :threshold="selected.threshold" :title="$t('qaHealth.chartTitle')" :dark="dark" />
        <div v-else class="qh-history-empty"><QaIcon :name="selected.status === 'stale' ? 'cloud_off' : 'bar_chart'" aria-hidden="true" /><strong>{{ $t(design ? selected.status === 'stale' ? 'qaHealth.staleHistory' : 'qaHealth.noHistory' : 'qaHealth.live.noHistory') }}</strong><p>{{ $t('qaHealth.noHistoryHint') }}</p></div>
        <dl class="qh-provenance"><div><dt>{{ $t('qaHealth.lastSuccess') }}</dt><dd>{{ lastSuccessStamp }}</dd></div><div><dt>{{ $t('qaHealth.window') }}</dt><dd>{{ observationWindow }}</dd></div><div><dt>{{ $t('qaHealth.source') }}</dt><dd>{{ moduleSource(selected) }}</dd></div></dl>
        <section class="qh-timeline"><h3>{{ $t('qaHealth.timeline') }}</h3><ol><li v-for="item in timeline" :key="item.at" :class="{'is-warning': item.warning}"><QaIcon :name="item.warning ? statusIcon(selected.status) : 'check_circle_filled'" aria-hidden="true" /><time>{{ item.at }}</time><span>{{ item.label }}</span></li></ol><p v-if="!timeline.length" class="qh-empty-timeline">{{ $t('qaHealth.live.noEvents') }}</p></section>
        <footer class="qh-footer"><span><QaIcon name="info" aria-hidden="true" />{{ $t(selected.status === 'healthy' ? 'qaHealth.qualitySeparate' : 'qaHealth.rootCausePending') }}</span><span>{{ $t('qaHealth.unknownNote') }}</span></footer>
      </article>
    </div>
    <dialog ref="evidenceDialog" class="qh-evidence-dialog" aria-labelledby="health-evidence-title" @cancel.prevent="closeEvidence" @click="closeOnBackdrop">
      <div v-if="evidenceOpen">
        <header><div><span class="qh-preview-label">{{ $t(preview ? 'qaHealth.preview' : 'qaHealth.live.observed') }}</span><h2 id="health-evidence-title">{{ moduleName(selected) }} · {{ $t('qaHealth.evidenceTitle') }}</h2></div><button class="qa-icon-button" data-testid="health-close-evidence" :aria-label="$t('qaHealth.close')" @click="closeEvidence"><QaIcon name="close" aria-hidden="true" /></button></header><p>{{ $t(preview ? 'qaHealth.evidenceHint' : 'qaHealth.live.evidenceHint') }}</p>
        <div class="qh-evidence-tabs" role="tablist" :aria-label="$t('qaHealth.evidenceViews')"><button v-for="tab in ['summary', 'raw']" :id="'health-evidence-tab-' + tab" :key="tab" :ref="(element) => rememberEvidenceTab(tab, element)" role="tab" :data-testid="'health-evidence-tab-' + tab" :tabindex="evidenceTab === tab ? 0 : -1" :aria-selected="evidenceTab === tab" :aria-controls="'health-evidence-panel-' + tab" @click="evidenceTab = tab" @keydown="navigateEvidenceTabs">{{ $t('qaHealth.evidenceTabs.' + tab) }}</button></div>
        <section v-show="evidenceTab === 'summary'" id="health-evidence-panel-summary" class="qh-evidence-summary" role="tabpanel" aria-labelledby="health-evidence-tab-summary" tabindex="0" data-testid="health-evidence-summary">
          <div class="qh-evidence-result" :class="'qh-tone-' + selected.status"><QaIcon :name="statusIcon(selected.status)" aria-hidden="true" /><div><strong>{{ $t('qaHealth.status.' + selected.status) }}</strong><p>{{ evidenceReason }}</p></div></div>
          <dl class="qh-evidence-facts"><div><dt>{{ moduleMetric(selected) }}</dt><dd>{{ formatValue(selected.value, selected.unit) }}</dd></div><div><dt>{{ $t('qaHealth.threshold') }}</dt><dd>{{ formatValue(selected.threshold, selected.unit) }}<small v-if="selected.id === 'agent' && selected.threshold !== null"> {{ $t('qaHealth.minimum') }}</small></dd></div><div v-if="selected.pending !== null"><dt>{{ $t('qaHealth.pending') }}</dt><dd>{{ selected.pending }} {{ $t('qaHealth.articles') }}</dd></div><div><dt>{{ $t('qaHealth.observed') }}</dt><dd>{{ observationStamp }} <small v-if="selected.observedAt">UTC+8</small></dd></div><div><dt>{{ $t('qaHealth.window') }}</dt><dd>{{ observationWindow }}</dd></div><div><dt>{{ $t('qaHealth.source') }}</dt><dd>{{ moduleSource(selected) }}</dd></div><template v-if="!design"><div v-for="(value, key) in selected.details" :key="key"><dt>{{ $t('qaHealth.live.details.' + key) }}</dt><dd>{{ key === 'frontend_revision' ? value : formatDetail(key, value) }}</dd></div></template></dl>
          <p class="qh-evidence-limit"><QaIcon name="info" aria-hidden="true" />{{ $t(selected.status === 'healthy' ? 'qaHealth.qualitySeparate' : 'qaHealth.rootCausePending') }} {{ $t('qaHealth.unknownNote') }}</p>
        </section>
        <section v-show="evidenceTab === 'raw'" id="health-evidence-panel-raw" role="tabpanel" aria-labelledby="health-evidence-tab-raw" tabindex="0"><pre tabindex="0">{{ evidenceJson }}</pre></section>
        <footer class="qh-evidence-actions"><button class="qa-button" data-testid="health-download" @click="downloadEvidence"><QaIcon name="download" aria-hidden="true" />{{ $t(preview ? 'qaHealth.download' : 'qaHealth.live.download') }}</button></footer>
      </div>
    </dialog>
  </section>
</template>

<script setup>
import { qaDownloadPrefix } from '../lib/runtime.js';
import { computed, nextTick, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import QaIcon from './QaIcon.vue';
import QaHealthTrend from './QaHealthTrend.vue';
import QaHealthHistory from './QaHealthHistory.vue';
import { healthTimestamp } from '../lib/qaHealth.js';
import { buildHealthOverview } from '../lib/qaHealthView.js';
import '../css/qa-health.css';
const props = defineProps({ dark: Boolean, model: { type: Object, required: true }, preview: Boolean, loading: Boolean });
const emit = defineEmits(['refresh']);
const design = computed(() => props.preview && !props.model.packet);
const { t, locale } = useI18n();
const modules = computed(() => props.model.modules);
const priority = props.model.modules.find((item) => item.status === 'critical') || props.model.modules.find((item) => item.status === 'warning');
const filter = ref('issues'), selectedId = ref(design.value ? 'indexer' : priority?.id || 'indexer'), refreshed = ref(false), mobileDetail = ref(false);
const detail = ref(null), master = ref(null), listHeading = ref(null), evidenceDialog = ref(null), evidenceButton = ref(null), evidenceOpen = ref(false), evidenceTab = ref('summary');
const moduleButtons = new Map(), evidenceTabs = new Map();
let listScroll = 0;
const issues = computed(() => modules.value.filter((item) => ['warning', 'critical'].includes(item.status)).sort((a, b) => (a.status === 'critical' ? -1 : 0) - (b.status === 'critical' ? -1 : 0))), healthy = computed(() => modules.value.filter((item) => item.status === 'healthy'));
const unobserved = computed(() => modules.value.filter((item) => !['healthy', 'warning', 'critical'].includes(item.status)));
const selected = computed(() => modules.value.find((item) => item.id === selectedId.value) || modules.value[0]);
const shownModules = computed(() => filter.value === 'all' ? modules.value : issues.value);
const overview = computed(() => buildHealthOverview(modules.value));
const countStates = computed(() => overview.value.counts.critical ? ['healthy', 'warning', 'critical', 'unknown'] : ['healthy', 'warning', 'unknown']);
const coverageLabel = computed(() => overview.value.coverage === null ? '—' : new Intl.NumberFormat(locale.value, { style: 'percent', maximumFractionDigits: 0 }).format(overview.value.coverage));
const snapshotStamp = computed(() => healthTimestamp(props.model.observedAt) || '—');
const observationStamp = computed(() => design.value ? snapshotStamp.value.slice(0, 10) + ' ' + selected.value.observedAt : selected.value.observedAt || '—');
const lastSuccessStamp = computed(() => design.value ? snapshotStamp.value.slice(0, 10) + ' ' + selected.value.lastSuccess : selected.value.lastSuccess || healthTimestamp(selected.value.details.last_success_at) || '—');
const observationWindow = computed(() => !design.value && selected.value.source === 'qa_llm_passive' ? t('qaHealth.lastQuarterHour') : design.value ? selected.value.id === 'llm' ? t('qaHealth.lastQuarterHour') : t('qaHealth.lastHour') : t('qaHealth.live.windows.' + (selected.value.value === null ? 'unmeasured' : ['crawler', 'indexer'].includes(selected.value.id) ? 'last_job' : 'instant')));
const visibleDetails = computed(() => Object.fromEntries(Object.entries(selected.value.details || {}).filter(([key, value]) =>
  selected.value.source === 'qa_llm_passive' && selected.value.details.completed_count === 0
    ? key === 'request_count' || ['cancelled_count', 'unclassified_count'].includes(key) && value > 0
    : !['window_seconds', 'last_success_at', 'window_limited'].includes(key))));
const thresholdRatio = computed(() => ['warning', 'critical'].includes(selected.value.status) && selected.value.threshold > 0 && selected.value.value > selected.value.threshold ? new Intl.NumberFormat(locale.value, { maximumFractionDigits: 1 }).format(selected.value.value / selected.value.threshold) : null);
const evidenceReason = computed(() => t(design.value ? 'qaHealth.evidenceReasons.' + selected.value.id : 'qaHealth.live.reasons.' + selected.value.reason, { value: formatValue(selected.value.value, selected.value.unit), threshold: formatValue(selected.value.threshold, selected.value.unit), pending: selected.value.pending, time: selected.value.observedAt }));
const timeline = computed(() => design.value ? selected.value.events.map((time, index) => ({ at: snapshotStamp.value.slice(0, 10) + ' ' + time, label: t('qaHealth.modules.' + selected.value.id + '.event' + index), warning: selected.value.status !== 'healthy' && index > 0 })) : selected.value.observedAt ? [{ at: selected.value.observedAt, label: t('qaHealth.live.reasonShort.' + selected.value.reason), warning: selected.value.status !== 'healthy' }] : []);
const moduleName = (item) => item.id === 'collector' ? t('qaHealth.collector') : item.name;
const statusIcon = (status) => status === 'healthy' ? 'check_circle_filled' : ['warning', 'critical'].includes(status) ? 'error_filled' : 'remove_circle';
const moduleTitle = (item) => t(design.value ? 'qaHealth.modules.' + item.id + '.title' : 'qaHealth.live.titles.' + item.id);
const moduleMetric = (item) => t(design.value ? 'qaHealth.modules.' + item.id + '.metric' : 'qaHealth.live.metrics.' + item.metric);
const moduleList = (item) => design.value ? t('qaHealth.modules.' + item.id + '.list') : t('qaHealth.live.reasonShort.' + item.reason) + (item.value === null ? '' : ' · ' + formatValue(item.value, item.unit));
const moduleSource = (item) => t((design.value ? 'qaHealth.sources.' : 'qaHealth.live.sources.') + item.source);
function formatValue(value, unit) { return value === null || unit === 'none' ? '—' : new Intl.NumberFormat(locale.value).format(value) + (unit === 'percent' ? '%' : ' ' + t('qaHealth.' + unit)); }
function formatDetail(key, value) { return value === null ? '—' : key === 'frontend_revision' ? value.slice(0, 12) : key === 'last_success_at' ? healthTimestamp(value) : key === 'window_limited' ? t('qaHealth.live.' + (value ? 'limited' : 'complete')) : key === 'mean_duration_ms' ? formatValue(value, 'milliseconds') : value; }
function failedDetail(key, value) { return key === 'http_status' ? value !== 200 : ['errors', 'skipped_embed_error', 'retry_pending', 'error_count', 'timeout_count', 'rate_limit_count'].includes(key) && value > 0; }
function rememberModuleButton(id, element) { if (element) moduleButtons.set(id, element); else moduleButtons.delete(id); }
function rememberEvidenceTab(id, element) { if (element) evidenceTabs.set(id, element); else evidenceTabs.delete(id); }
async function selectModule(id) { selectedId.value = id; if (window.matchMedia('(max-width: 1000px)').matches) { const workspace = master.value?.closest('.qa-workspace'); listScroll = workspace?.scrollTop || 0; mobileDetail.value = true; await nextTick(); detail.value?.focus({ preventScroll: true }); if (workspace) workspace.scrollTop = 0; } }
async function returnToIssues() { mobileDetail.value = false; await nextTick(); (moduleButtons.get(selectedId.value) || listHeading.value)?.focus({ preventScroll: true }); const workspace = master.value?.closest('.qa-workspace'); if (workspace) workspace.scrollTop = listScroll; }
function refreshPreview() { refreshed.value = true; emit('refresh'); }
const evidenceJson = computed(() => JSON.stringify(design.value ? { kind: 'synthetic_design_preview', live: false, environment: props.model.environment, version: props.model.version, observed_at: props.model.observedAt, module: selected.value.id, status: selected.value.status, score: null, score_basis: 'Not calculated; production scoring rules are not implemented.', observation_coverage: { observed: overview.value.observed, total: overview.value.total }, measurements: { value: selected.value.value, unit: selected.value.unit, threshold: selected.value.threshold, pending_articles: selected.value.pending, observed_at: props.model.observedAt.slice(0, 10) + 'T' + selected.value.observedAt.slice(-8) + '+08:00' }, samples: selected.value.samples, root_cause: null, quality_review: 'pending' } : { kind: props.preview ? 'synthetic_design_preview' : 'observed_health', live: !props.preview, environment: 'qa', scope: props.model.packet.scope, generated_at: props.model.observedAt, source_sha: props.model.packet.source_sha, module: selected.value.id, view_state: { status: selected.value.status, fresh: selected.value.fresh }, observation: selected.value.raw, observation_coverage: { observed: overview.value.observed, total: overview.value.total }, quality_review: 'unmeasured', score: null }, null, 2));
async function openEvidence() { evidenceTab.value = 'summary'; evidenceOpen.value = true; await nextTick(); evidenceDialog.value?.showModal?.(); }
async function navigateEvidenceTabs(event) { if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); evidenceTab.value = event.key === 'Home' ? 'summary' : event.key === 'End' ? 'raw' : evidenceTab.value === 'summary' ? 'raw' : 'summary'; await nextTick(); evidenceTabs.get(evidenceTab.value)?.focus(); }
function closeEvidence() { evidenceDialog.value?.close?.(); evidenceOpen.value = false; evidenceButton.value?.focus(); }
function closeOnBackdrop(event) { if (event.target === evidenceDialog.value) { const rect = evidenceDialog.value.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) closeEvidence(); } }
function downloadEvidence() { const url = URL.createObjectURL(new Blob([evidenceJson.value], { type: 'application/json' })); const link = document.createElement('a'); link.href = url; link.download = qaDownloadPrefix() + '-health-' + selected.value.id + (props.preview ? '-design-preview.json' : '-observed.json'); link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); }
</script>
